{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "MK-458, a polar N-propyl morpholine analogue with a phenolic hydroxyl, had an absolute oral bioavailability of approximately 5% in Parkinson's patients, supporting low oral bioavailability for the similarly polar, ionizable query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "3-PPP, a propylpiperidine phenol analogue, failed in clinical trials due to low oral bioavailability, supporting the expectation that the query's polar/ionizable features limit systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Compound 26, a close structural analogue with a propylmorpholine and phenol, was predicted to have 0% oral bioavailability in humans, reinforcing a low-F outcome for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Milnacipran showed high absolute oral bioavailability (85 ± 3%) in humans, but its small flexible cyclopropane-amine structure is not representative of the query's permanently charged quaternary ammonium and polyhydroxylated rigid scaffold, so this high-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%). The query is a permanently charged quaternary ammonium alkaloid with multiple hydroxyl groups and a large rigid polycyclic structure, which strongly favors poor membrane permeability and low oral absorption. Supporting low-F analogues (MK-458 ~5%, 3-PPP low, compound 26 ~0%) are more relevant to this polar/ionizable phenotype than high-F tertiary amine drugs such as milnacipran.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact quaternary ammonium scaffold.",
    "All retrieved analogues have low Morgan similarity (~0.19), limiting quantitative transferability.",
    "No human PK data for a close quaternary ammonium analogue with multiple hydroxyls."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

